func:
if (flow.get('is_processing') === true) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'Locked (already processing)' });
    return null;
}

flow.set('is_processing', true);
node.status({ fill: 'blue', shape: 'dot', text: 'Lock acquired' });
return msg;

var content = msg.payload || '';
var lines = content.split('\n');
var adapter = 'live_opencode';
var nodeRedUrl = 'http://localhost:1880';

for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (line === '' || line.indexOf('#') === 0) continue;
    var parts = line.split(':');
    if (parts.length >= 2) {
        var key = parts[0].trim();
        var val = parts.slice(1).join(':').trim();
        // Strip quotes
        if ((val.indexOf('"') === 0 && val.lastIndexOf('"') === val.length - 1) ||
            (val.indexOf("'") === 0 && val.lastIndexOf("'") === val.length - 1)) {
            val = val.substring(1, val.length - 1);
        }
        if (key === 'agent_adapter') {
            var adapterParts = val.split(':');
            adapter = adapterParts.length > 1 ? adapterParts[1].trim() : val;
        } else if (key === 'node_red_url') {
            nodeRedUrl = val;
        }
    }
}

msg.adapter = adapter;
msg.nodeRedUrl = nodeRedUrl;
node.status({ fill: 'green', shape: 'dot', text: 'Adapter: ' + adapter });
return msg;

var stdout = (msg.payload || '').trim();
if (stdout !== '') {
    try {
        var failedTasks = JSON.parse(stdout);
        if (failedTasks && failedTasks.length > 0) {
            node.warn('Router blocked by failed task: ' + failedTasks[0].id + '. Waiting for Owner intervention...');
            node.status({ fill: 'red', shape: 'dot', text: 'Blocked by failed task: ' + failedTasks[0].id });
            flow.set('is_processing', false);
            return null;
        }
    } catch (e) {
        node.error('Error parsing failed tasks: ' + e.message);
    }
}
node.status({ fill: 'green', shape: 'ring', text: 'No blocked tasks' });
return msg;

var stdout = (msg.payload || '').trim();
if (stdout !== '') {
    try {
        var stuckTasks = JSON.parse(stdout);
        if (stuckTasks && stuckTasks.length > 0) {
            var task = stuckTasks[0];
            node.status({ fill: 'cyan', shape: 'dot', text: 'Lead Escalation for task ' + task.id });
            msg.task = task;
            msg.assigneeID = 5;
            return [null, msg];
        }
    } catch (e) {
        node.error('Error parsing stuck tasks: ' + e.message);
    }
}
return [msg, null];

var stdout = (msg.payload || '').trim();
if (stdout === '') {
    node.status({ fill: 'green', shape: 'ring', text: 'All tasks finished' });
    flow.set('is_processing', false);
    return null;
}
try {
    var tasks = JSON.parse(stdout);
    if (!tasks || tasks.length === 0) {
        node.status({ fill: 'green', shape: 'ring', text: 'All tasks finished' });
        flow.set('is_processing', false);
        return null;
    }
    var task = tasks[0];
    msg.task = task;
    msg.assigneeID = task.agent_id ? parseInt(task.agent_id) : 2;
    node.status({ fill: 'blue', shape: 'dot', text: 'Task ID: ' + task.id + ' (Assignee: ' + msg.assigneeID + ')' });
    return msg;
} catch (e) {
    node.error('Error parsing todo task: ' + e.message);
    flow.set('is_processing', false);
    return null;
}

if (!msg.task.agent_id) {
    msg.needs_db_assignment = true;
    msg.assigneeID = 2;
}
return msg;
